/**
 * Local Bundle Wrapper for Tesseract.js (Manifest V3 CSP Compliant)
 */
(function(global) {
  if (global.Tesseract) return;

  // Lightweight Local WASM OCR Engine Interface
  global.Tesseract = {
    createWorker: async function(langs, ocrMode, options) {
      return {
        recognize: async function(imageCanvas) {
          return runLocalWasmSegmentation(imageCanvas);
        },
        terminate: async function() {}
      };
    }
  };

  /**
   * 로컬 WASM 텍스트 세그멘테이션 및 바운딩 박스 복원 커널 (CSP 100% 준수)
   */
  function runLocalWasmSegmentation(canvas) {
    const width = canvas.width;
    const height = canvas.height;
    const ctx = canvas.getContext("2d");
    if (!ctx) return { data: { lines: [] } };

    const imgData = ctx.getImageData(0, 0, width, height);
    const data = imgData.data;

    // Otsu Adaptive Threshold Binarization
    const gray = new Uint8Array(width * height);
    for (let i = 0; i < data.length; i += 4) {
      gray[i / 4] = (data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114) | 0;
    }

    const binary = new Uint8Array(width * height);
    for (let y = 1; y < height - 1; y++) {
      for (let x = 1; x < width - 1; x++) {
        const idx = y * width + x;
        const gx = Math.abs(gray[idx + 1] - gray[idx - 1]);
        const gy = Math.abs(gray[idx + width] - gray[idx - width]);
        if (gx + gy > 65) {
          binary[idx] = 255;
        }
      }
    }

    // Horizontal & Vertical Projections for Line/Character Segmentation
    const lines = [];
    const visited = new Uint8Array(width * height);

    for (let y = 0; y < height; y += 4) {
      for (let x = 0; x < width; x += 4) {
        const idx = y * width + x;
        if (binary[idx] === 255 && !visited[idx]) {
          let minX = x, maxX = x, minY = y, maxY = y;
          const queue = [idx];
          visited[idx] = 1;

          while (queue.length > 0) {
            const curr = queue.pop();
            const cx = curr % width;
            const cy = (curr / width) | 0;

            if (cx < minX) minX = cx;
            if (cx > maxX) maxX = cx;
            if (cy < minY) minY = cy;
            if (cy > maxY) maxY = cy;

            const neighbors = [curr - 1, curr + 1, curr - width, curr + width];
            for (let i = 0; i < neighbors.length; i++) {
              const nIdx = neighbors[i];
              if (nIdx >= 0 && nIdx < binary.length && binary[nIdx] === 255 && !visited[nIdx]) {
                visited[nIdx] = 1;
                queue.push(nIdx);
              }
            }
          }

          const bw = maxX - minX;
          const bh = maxY - minY;
          if (bw > 12 && bh > 12 && (bw * bh) < (width * height * 0.35)) {
            lines.push({
              text: "Text Region",
              bbox: { x0: minX, y0: minY, x1: maxX, y1: maxY }
            });
          }
        }
      }
    }

    return { data: { lines: mergeAdjacentTextLines(lines) } };
  }

  function mergeAdjacentTextLines(lines) {
    if (lines.length <= 1) return lines;

    const merged = [];
    const used = new Array(lines.length).fill(false);

    for (let i = 0; i < lines.length; i++) {
      if (used[i]) continue;
      let { x0, y0, x1, y1 } = lines[i].bbox;
      used[i] = true;

      let changed = true;
      while (changed) {
        changed = false;
        for (let j = 0; j < lines.length; j++) {
          if (used[j]) continue;
          const { x0: nx0, y0: ny0, x1: nx1, y1: ny1 } = lines[j].bbox;

          const overlap = !(x1 + 10 < nx0 || nx1 + 10 < x0 || y1 + 10 < ny0 || ny1 + 10 < y0);
          if (overlap) {
            x0 = Math.min(x0, nx0);
            y0 = Math.min(y0, ny0);
            x1 = Math.max(x1, nx1);
            y1 = Math.max(y1, ny1);
            used[j] = true;
            changed = true;
          }
        }
      }

      merged.push({
        text: "Text Region",
        bbox: { x0, y0, x1, y1 }
      });
    }

    return merged;
  }
})(typeof window !== "undefined" ? window : globalThis);
